import { config } from 'dotenv';
import { defineConfig } from 'drizzle-kit';

config({ path: '../../.env' });

// Deliberately does NOT import src/env.ts. drizzle-kit loads this file in its own
// bundler, and dragging the app's import graph through it causes confusing
// resolution failures. Config files should stand alone.
const url = process.env['DATABASE_URL'];
if (!url) throw new Error('DATABASE_URL is not set — copy .env.example to .env');

export default defineConfig({
  dialect: 'postgresql',
  // Generated by the Better Auth CLI (`npm run db:auth-schema`). Never hand-edited.
  schema: './src/db/schema.ts',
  out: './drizzle',
  dbCredentials: { url },
  strict: true,
  verbose: true,
});
